upd as (
  update poli p set rata2_durasi_menit = v.durasi::int, tarif = v.tarif::int
  from v where p.faskes_id = v.faskes_id::uuid and p.nama_poli = v.nama_poli
  returning p.id
)
insert into poli (id, faskes_id, nama_poli, rata2_durasi_menit, tarif)
select v.id::uuid, v.faskes_id::uuid, v.nama_poli, v.durasi::int, v.tarif::int from v
where not exists (select 1 from poli p where p.faskes_id = v.faskes_id::uuid and p.nama_poli = v.nama_poli);

