upd as (
  update obat o set kelompok = v.kelompok, satuan = v.satuan, stok = v.stok::int, harga = v.harga::int, ditanggung = v.ditanggung::boolean
  from v where o.faskes_id = v.faskes_id::uuid and o.nama = v.nama
  returning o.id
)
insert into obat (id, faskes_id, nama, kelompok, satuan, stok, harga, ditanggung)
select v.id::uuid, v.faskes_id::uuid, v.nama, v.kelompok, v.satuan, v.stok::int, v.harga::int, v.ditanggung::boolean from v
where not exists (select 1 from obat o where o.faskes_id = v.faskes_id::uuid and o.nama = v.nama);

